import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import javax.servlet.http.HttpServletRequest;

public void executePingSafe(HttpServletRequest request) throws IOException {
    String ipAddress = request.getParameter("ip");

    // PROPER USAGE:
    // 1. Input Validation: Ensure the input matches the expected format (e.g., an IP address regex).
    if (ipAddress == null || !ipAddress.matches("^\\d+\\.\\d+\\.\\d+\\.\\d+$")) {
        throw new IllegalArgumentException("Invalid IP format");
    }

    // 2. API Fix: Use ProcessBuilder.
    // By passing arguments as a list, the Java API treats the IP address as a single argument literal.
    // The shell will not interpret special characters (like ; or &&) inside the argument.
    List<String> command = new ArrayList<>();
    command.add("ping");
    command.add("-c");
    command.add("3");
    command.add(ipAddress);

    ProcessBuilder pb = new ProcessBuilder(command);
    Process process = pb.start();
}
